create extension if not exists "uuid-ossp";
create type patient_status as enum ('active','suspended','completed');
create type goal_status as enum ('not_started','in_progress','consolidation','achieved','suspended');
create type appointment_type as enum ('regular','assessment','checkup','cancelled');
create table profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, created_at timestamptz default now(), updated_at timestamptz default now());
create table patients (id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade, first_name text not null, last_name text not null, birth_date date, phone text, guardian_name text, school text, school_class text, referral_reason text, notes text, status patient_status not null default 'active', created_at timestamptz default now(), updated_at timestamptz default now());
create table appointments (id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade, patient_id uuid not null references patients(id) on delete cascade, starts_at timestamptz not null, duration_minutes int not null default 45, type appointment_type not null default 'regular', notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table goals (id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade, patient_id uuid not null references patients(id) on delete cascade, title text not null, description text, priority smallint default 2 check(priority between 1 and 3), status goal_status not null default 'not_started', progress smallint default 0 check(progress between 0 and 100), created_at timestamptz default now(), updated_at timestamptz default now());
create table sessions (id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade, patient_id uuid not null references patients(id) on delete cascade, appointment_id uuid references appointments(id) on delete set null, occurred_at timestamptz not null default now(), duration_minutes int, activities text, patient_response text, help_level text, result text, next_session_plan text, homework text, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table session_goals (session_id uuid references sessions(id) on delete cascade, goal_id uuid references goals(id) on delete cascade, primary key(session_id,goal_id));
create table materials (id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, description text, category text, tags text[] default '{}', file_name text, storage_path text, mime_type text, file_size bigint, external_url text, is_favorite boolean default false, created_at timestamptz default now(), updated_at timestamptz default now(), check(storage_path is not null or external_url is not null));
create table session_materials (session_id uuid references sessions(id) on delete cascade, material_id uuid references materials(id) on delete cascade, primary key(session_id,material_id));
create table patient_materials (patient_id uuid references patients(id) on delete cascade, material_id uuid references materials(id) on delete cascade, primary key(patient_id,material_id));
alter table profiles enable row level security; alter table patients enable row level security; alter table appointments enable row level security; alter table goals enable row level security; alter table sessions enable row level security; alter table materials enable row level security;
alter table session_goals enable row level security; alter table session_materials enable row level security; alter table patient_materials enable row level security;
create policy "own profile" on profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "own patients" on patients for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own appointments" on appointments for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own goals" on goals for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own sessions" on sessions for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own materials" on materials for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own session goals" on session_goals for all using (exists(select 1 from sessions s where s.id=session_id and s.user_id=auth.uid())) with check (exists(select 1 from sessions s where s.id=session_id and s.user_id=auth.uid()) and exists(select 1 from goals g where g.id=goal_id and g.user_id=auth.uid()));
create policy "own session materials" on session_materials for all using (exists(select 1 from sessions s where s.id=session_id and s.user_id=auth.uid())) with check (exists(select 1 from sessions s where s.id=session_id and s.user_id=auth.uid()) and exists(select 1 from materials m where m.id=material_id and m.user_id=auth.uid()));
create policy "own patient materials" on patient_materials for all using (exists(select 1 from patients p where p.id=patient_id and p.user_id=auth.uid())) with check (exists(select 1 from patients p where p.id=patient_id and p.user_id=auth.uid()) and exists(select 1 from materials m where m.id=material_id and m.user_id=auth.uid()));
-- Create a private `therapy-materials` bucket in Storage. File paths must start with auth.uid()::text.
create policy "private material read" on storage.objects for select using (bucket_id='therapy-materials' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "private material write" on storage.objects for insert with check (bucket_id='therapy-materials' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "private material update" on storage.objects for update using (bucket_id='therapy-materials' and (storage.foldername(name))[1]=auth.uid()::text) with check (bucket_id='therapy-materials' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "private material delete" on storage.objects for delete using (bucket_id='therapy-materials' and (storage.foldername(name))[1]=auth.uid()::text);
